"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command "@'
[Reflection.Assembly]::LoadWithPartialName('System.Web.Extensions') | Out-Null
"'$s = New-Object System.Web.Script.Serialization.JavaScriptSerializer
$s.MaxJsonLength = 2147483647
$p = '"'C:\\Users\\hzq00\\.codex\\sessions\\2026\\08\\10\\rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl'
"'$cut = [datetime]'"'2026-08-14T06:00:00Z'
"'$sr = New-Object System.IO.StreamReader($p)
$typeCount = @{}; $lastTs = $null; $hits = New-Object System.Collections.ArrayList
while (-not $sr.EndOfStream) {
  $line = $sr.ReadLine()
  if ([string]::IsNullOrWhiteSpace($line)) { continue }
  try { $o = $s.DeserializeObject($line) } catch { continue }
  $ts = [string]$o['"'timestamp']
  "'$tv = $null; [void][datetime]::TryParse($ts,[ref]$tv)
  if ($tv) { $lastTs = $ts }
  if ($tv -and $tv -ge $cut) {
    $t = [string]$o['"'type']
    if (-not "'$typeCount.ContainsKey($t)) { $typeCount[$t]=0 }
    $typeCount[$t]++
    if ($Hits.Count -lt 12 -or $Hits.Count -ge 12) { [void]$Hits.Add(@{ts=$ts; obj=$o}) }
  }
}
$sr.Close()
'"'expected payload types:'
"'$typeCount.GetEnumerator() | Sort-Object Name | ForEach-Object { '"'{0}: {1}' -f "'$_.Key, $_.Value }
'"'last timestamp: {0}' -f "'$lastTs
'"'hits kept: {0}' -f "'$Hits.Count
'"'@ | Out-Null"

