  try { $o = $s.DeserializeObject($line) } catch { continue }
  $tv = $null
  if (-not [datetime]::TryParse([string]$o['"'timestamp'], [ref]"'$tv)) { continue }
  $lastTs = [string]$o['"'timestamp']
