    $n++
    $key = [string]$o['"'type']
    if (-not "'$typeCount.ContainsKey($key)) { $typeCount[$key] = 0 }
    $typeCount[$key] = $typeCount[$key] + 1
  }
}
$sr.Close()
Write-Output ('"'events_in_window: ' + "'$n)
$typeCount.GetEnumerator() | ForEach-Object { Write-Output ($_.Key + '"': ' + "'$_.Value) }
Write-Output ('"'last_timestamp: ' + "'$lastTs)'

